var o=[{title:`As principais variações`,text:`Num agachamento split os pés mantêm-se assentes numa posição escalonada. Um avanço para trás recua em cada repetição, e um avanço para a frente ou em caminhada leva o corpo para uma nova posição. Um step-up sobe-o para uma plataforma estável, e um agachamento split com o pé de trás elevado torna o exercício mais difícil. As variações sobrepõem-se, mas diferem na exigência de equilíbrio e no quanto o joelho e a anca se deslocam. Todas funcionam bem a par dos agachamentos e dobradiças com as duas pernas.`},{title:`Técnica básica`,text:`Num agachamento split, adote uma posição suficientemente larga para ficar seguro, desça na vertical dobrando o joelho e a anca com controlo e depois suba através da perna de trabalho. Mantenha o pé da frente assente no chão e deixe o joelho seguir um percurso confortável. Uma ligeira inclinação do tronco para a frente pode ser normal. O melhor comprimento de passada depende das proporções do seu corpo e do que está a treinar.`},{title:`Equilíbrio e segurança`,text:`Enquanto aprende, agarre-se a uma parede ou corrimão com uma mão. Se o exercício se transformar num teste de equilíbrio, encurte o passo, reduza a profundidade ou use menos peso até voltar a ser trabalho de força controlado. Evite caixas instáveis e degraus muito altos. Se o movimento continuar a causar dor articular, pare ou mude para outro exercício.`},{title:`Comparar os lados`,text:`Comece pelo lado em que se sente menos confiante e depois iguale o número de boas repetições no outro lado. Por exemplo, faça duas séries de seis avanços para trás por perna segurando um apoio. Pequenas diferenças entre os lados não significam que esteja lesionado, e um melhor controlo ao longo do tempo é um bom objetivo. Progrida largando primeiro o apoio, depois acrescentando repetições e depois acrescentando resistência.`}];var s=[{label:`Biblioteca de exercícios da ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`NSCA: segurança e fundamentos do treino de resistência`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Mayo Clinic: técnica de treino com pesos (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var r={sections:o,sources:s};export{r as default,o as sections,s as sources};